<?php

namespace App\Controllers;

use App\Core\Auth;
use App\Core\RateLimiter;
use App\Services\AuditService;
use App\Services\InviteService;
use App\Core\Session;

/**
 * Unlinked developer console for issuing Dean invitation codes.
 *
 * The only credential is the high-entropy developer key embedded in the URL.
 * It is generated by the installer and stored in config/local.php. There is
 * deliberately no navigation link, login form, or discovery endpoint.
 */
final class DeveloperController extends BaseController
{
    private InviteService $invites;

    public function __construct()
    {
        $this->invites = new InviteService();
    }

    public function index(string $key): void
    {
        $this->guard($key);
        $generated = Session::pull('_developer_invite');
        $this->view('developer/index', [
            'pageTitle' => 'Dean invitation codes',
            'invites' => $this->invites->all(),
            'generated' => is_array($generated) ? $generated : null,
            'developerKey' => $key,
        ], 'layouts/developer');
    }

    public function store(string $key): void
    {
        $this->guard($key);
        $this->requirePost();

        if (RateLimiter::tooMany('developer.invite', 40, 3600)) {
            $this->error('Too many invitation codes were requested from this network. Try again later.', 'developer/' . rawurlencode($key));
        }

        $maxUses = max(1, min(InviteService::MAX_USES_LIMIT, $this->intInput('max_uses', 1)));
        $validDays = max(1, min(InviteService::MAX_VALID_DAYS, $this->intInput('valid_days', 7)));
        $note = $this->postString('note');
        if (mb_strlen($note) > 190) {
            $this->error('The note is too long. Keep it under 190 characters.', 'developer/' . rawurlencode($key));
        }

        $invite = $this->invites->create('dean', $maxUses, $validDays, $note, Auth::id());
        (new AuditService())->record(
            'invite.create',
            'registration_invite',
            (int) $invite['id'],
            'Created a Dean invitation code (' . $maxUses . ' use(s), expires ' . $invite['expires_at'] . ')'
        );

        Session::set('_developer_invite', $invite);
        $this->success('Dean invitation code created. Copy it now — it is shown only once.', 'developer/' . rawurlencode($key));
    }

    public function revoke(string $key, string $id): void
    {
        $this->guard($key);
        $this->requirePost();

        $invite = $this->invites->find((int) $id);
        if (!$invite) {
            abort(404);
        }
        if ($this->invites->revoke((int) $id)) {
            (new AuditService())->record(
                'invite.revoke',
                'registration_invite',
                (int) $id,
                'Revoked a Dean invitation code ending ' . (string) $invite['code_hint']
            );
            $this->success('Invitation code revoked.', 'developer/' . rawurlencode($key));
        }
        $this->error('That invitation code was already revoked or is unavailable.', 'developer/' . rawurlencode($key));
    }

    private function guard(string $key): void
    {
        header('X-Robots-Tag: noindex, nofollow, noarchive');
        header('Referrer-Policy: no-referrer');
        header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');

        $configured = trim((string) config('app.developer_key', ''));
        if ($configured === '' || $key === '' || !hash_equals($configured, $key)) {
            abort(404);
        }
    }
}
